<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {api,req,type AccountRow} from '../api'
import {canChangeAccount} from '../workGuard'
import {refreshAll,toast} from '../store'
import Countdown from '../components/Countdown.vue'
import Icon from '../components/Icon.vue'
type Item=AccountRow&{active:{label?:string;note?:string;since?:string};next?:{label:string;at:number};running:boolean;enabled:string[];pending:number;hourly_used:number;recent?:{at:string;note:string}}
const rows=ref<Item[]>([]),error=ref(''),at=ref(''),busy=ref(0),loading=ref(true)
const router=useRouter();let alive=true,timer:ReturnType<typeof setInterval>|undefined
const running=computed(()=>rows.value.filter(r=>r.running).length)
function when(v:string|number){return new Date(typeof v==='number'?v*1000:v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})}
async function load(){try{const data=await req<{items:Item[];at:string}>('/api/standby');if(alive){rows.value=data.items;at.value=data.at;error.value=''}}catch(e){if(alive)error.value=String(e)}finally{loading.value=false}}
async function open(r:Item,path:string){if(busy.value||!r.ready||!await canChangeAccount())return;busy.value=r.id;try{if(!r.current){await api.switchAccount(r.id);await refreshAll()}await router.push(path)}catch(e){toast(String(e),'danger')}finally{busy.value=0}}
onMounted(()=>{void load();timer=setInterval(()=>void load(),5000)})
onUnmounted(()=>{alive=false;if(timer)clearInterval(timer)})
</script>
<template><div class="standby-workspace">
<header class="standby-heading"><div><h1><Icon name="clock"/>挂机中心</h1><span class="muted">{{rows.length}} 个账号 · {{running}} 个已开启自动任务</span></div><div class="standby-updated"><span v-if="at" class="muted">更新于 {{when(at)}}</span><button @click="load">刷新</button></div></header>
<p v-if="error" class="warning" role="alert">{{error}}</p>
<p v-if="loading&&!rows.length" class="empty-state">读取中…</p>
<div class="account-grid"><article v-for="r in rows" :key="r.id" class="panel account-card" :class="{'account-running':r.running,'account-busy':r.active.label}">
<header class="account-heading"><img v-if="r.avatar" :src="r.avatar" referrerpolicy="no-referrer" class="account-avatar" alt="" @error="($event.target as HTMLImageElement).style.visibility='hidden'"/><span v-else class="account-avatar initial">{{r.nickname.slice(0,1)}}</span><div class="account-name"><strong>{{r.nickname}}</strong><span class="muted">{{r.uid}}<span v-if="r.current"> · 当前账号</span></span></div><span class="chip" :class="!r.ready?'chip-danger':r.active.label?'chip-ok':r.running?'chip-ok':''">{{!r.ready?'需登录':r.active.label?'执行中':r.running?'待机':'未开启'}}</span></header>
<section class="current-task"><span class="task-label"><Icon name="queue" :size="16"/>当前事项</span><strong>{{r.active.label||(!r.ready?'登录后继续':r.running?'等待下一项':'暂无任务')}}</strong><p :title="r.active.note">{{r.active.note||'—'}}</p><span class="muted task-time">{{r.active.since?'开始于 '+when(r.active.since):' '}}</span></section>
<section class="next-task-card"><div><span class="task-label"><Icon name="clock" :size="16"/>下一事项</span><strong>{{r.next?.label||'暂无排期'}}</strong><span class="muted task-time">{{r.next?when(r.next.at):'—'}}</span></div><div class="countdown-box"><span class="muted">距离执行</span><Countdown v-if="r.next" :at="r.next.at"/><span v-else>—</span></div></section>
<div class="account-metrics"><span>待参与 <b>{{r.pending}}</b></span><span>近 1 小时尝试 <b>{{r.hourly_used}}</b></span></div>
<div class="task-functions"><span v-for="label in r.enabled" :key="label" class="chip">{{label}}</span><span v-if="!r.enabled.length" class="muted">{{r.running?'订阅自动更新':'未开启定时任务'}}</span></div>
<div class="last-task"><span class="task-label">最近记录 <time v-if="r.recent">{{when(r.recent.at)}}</time></span><p :title="r.recent?.note">{{r.recent?.note||'暂无运行记录'}}</p></div>
<footer><button :disabled="!!busy||!r.ready" @click="open(r,'/auto')"><Icon name="settings" :size="16"/>任务设置</button><button :disabled="!!busy||!r.ready" @click="open(r,'/activity')">运行记录</button><button :disabled="!!busy||!r.ready" @click="open(r,'/inbox')">消息</button></footer>
</article></div>
</div></template>
<style scoped>
.standby-workspace{max-width:1440px;margin:auto;display:grid;gap:20px}.standby-heading,.standby-updated{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.standby-heading h1{display:flex;gap:10px;align-items:center;font-size:20px;margin:0 0 8px}.standby-updated{font-size:var(--text-meta)}.account-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,360px),1fr));gap:20px;align-items:stretch}.account-card{min-width:0;display:flex;flex-direction:column;overflow:hidden;border-top:3px solid var(--line)}.account-running{border-top-color:var(--accent)}.account-busy{border-top-color:var(--discover)}.account-heading{display:flex;gap:12px;align-items:center;padding:20px;border-bottom:1px solid var(--line);background:var(--surface-2)}.account-avatar{width:42px;height:42px;border-radius:50%;object-fit:cover;flex:none}.initial{display:grid;place-items:center;background:var(--discover-soft);color:var(--discover)}.account-name{min-width:0;flex:1;display:grid;gap:5px}.account-name strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:16px}.account-name span{font-size:var(--text-meta)}.current-task{grid-template-rows:20px 24px 44px 18px;min-height:170px;margin:18px 18px 0;padding:16px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--surface-2);display:grid;gap:8px}.task-label{display:flex;align-items:center;gap:7px;color:var(--muted);font-size:var(--text-meta)}.current-task>strong,.next-task-card strong{font-size:16px}.current-task p{min-height:44px;line-height:1.6;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;margin:0}.task-time{font-size:var(--text-meta);min-height:18px}.next-task-card{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:16px;padding:20px 18px}.next-task-card>div:first-child{display:grid;gap:8px}.next-task-card strong{overflow-wrap:anywhere}.countdown-box{display:flex;flex-direction:column;align-items:flex-end;justify-content:center;gap:8px;color:var(--discover)}.countdown-box .countdown{font-size:23px}.countdown-box>.muted{font-size:var(--text-meta)}.account-metrics{display:flex;justify-content:space-between;gap:12px;padding:14px 18px;background:var(--discover-soft);font-size:var(--text-meta)}.account-metrics b{margin-left:8px;font-size:17px;color:var(--discover)}.task-functions{display:flex;flex-wrap:wrap;align-content:flex-start;gap:8px;padding:18px;min-height:94px}.last-task{padding:0 18px 18px;flex:1}.last-task time{margin-left:auto;font-size:12px}.last-task p{line-height:1.6;margin:10px 0 0;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;min-height:44px}.account-card footer{display:flex;flex-wrap:wrap;gap:8px;padding:16px 18px;border-top:1px solid var(--line)}
</style>
